'use client';

import { useState } from 'react';

import { Button } from '@/registry/ndeko/ui/button';

import { FernpostMark } from './brand-mark';
import { DEFAULT_LINK_ID, NAV_LINKS } from './data';
import { MobileSheet } from './mobile-sheet';
import { NavLinks } from './nav-links';

export default function Headers02() {
  const [currentId, setCurrentId] = useState(DEFAULT_LINK_ID);

  return (
    <header className='px-4 pt-4 sm:px-6'>
      <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] mx-auto flex h-14 max-w-4xl items-center gap-3 rounded-full ps-4 pe-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <a
          href='#'
          className='focus-visible:ring-ring/25 flex items-center gap-2 rounded-full text-sm font-semibold outline-none focus-visible:ring-[3px]'
        >
          <FernpostMark />
          Fernpost
        </a>
        <div className='flex flex-1 justify-center'>
          <NavLinks
            links={NAV_LINKS}
            currentId={currentId}
            onNavigate={setCurrentId}
          />
        </div>
        <div className='flex items-center gap-1'>
          <Button
            variant='ghost'
            className='hidden md:inline-flex'
            nativeButton={false}
            render={<a href='#' />}
          >
            Sign in
          </Button>
          <Button nativeButton={false} render={<a href='#' />}>
            Start writing
          </Button>
          <MobileSheet
            links={NAV_LINKS}
            currentId={currentId}
            onNavigate={setCurrentId}
          />
        </div>
      </div>
    </header>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

import { type NavLink } from './data';

const HIGHLIGHT_TRANSITION: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};

const INSTANT_LAYOUT: Transition = {
  layout: { duration: 0 },
  opacity: { duration: 0.15 },
};

function highlightTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT_LAYOUT;
  }
  return HIGHLIGHT_TRANSITION;
}

function currentAttributeOf(isCurrent: boolean) {
  if (isCurrent) {
    return 'page' as const;
  }
  return undefined;
}

type NavLinksProps = {
  links: NavLink[];
  currentId: string;
  onNavigate: (id: string) => void;
};

export function NavLinks({ links, currentId, onNavigate }: NavLinksProps) {
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const highlightTransition = highlightTransitionOf(shouldReduceMotion);

  function clearHover() {
    setHoveredId(null);
  }

  return (
    <nav aria-label='Main' className='hidden md:block'>
      <ul className='flex items-center' onPointerLeave={clearHover}>
        {links.map((link) => {
          const isHovered = hoveredId === link.id;
          const isCurrent = currentId === link.id;

          function highlight() {
            setHoveredId(link.id);
          }

          function navigate() {
            onNavigate(link.id);
          }

          return (
            <li key={link.id}>
              <a
                href={link.href}
                aria-current={currentAttributeOf(isCurrent)}
                onPointerEnter={highlight}
                onFocus={highlight}
                onBlur={clearHover}
                onClick={navigate}
                className='text-muted-foreground hover:text-foreground aria-[current=page]:text-foreground focus-visible:ring-ring/25 relative inline-flex h-8 items-center rounded-full px-3 text-[13px] font-medium transition-colors outline-none focus-visible:ring-[3px]'
              >
                <AnimatePresence>
                  {isHovered && (
                    <motion.span
                      layoutId='headers-02-highlight'
                      aria-hidden='true'
                      className='bg-foreground/5 absolute inset-0 rounded-full'
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                      transition={highlightTransition}
                    />
                  )}
                </AnimatePresence>
                <span className='relative'>{link.label}</span>
              </a>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

'use client';

import { useState } from 'react';

import { MenuIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { SelectedMark } from '@/registry/ndeko/ui/selected-mark';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from '@/registry/ndeko/ui/sheet';

import { FernpostMark } from './brand-mark';
import { type NavLink } from './data';

function currentAttributeOf(isCurrent: boolean) {
  if (isCurrent) {
    return 'page' as const;
  }
  return undefined;
}

type MobileSheetProps = {
  links: NavLink[];
  currentId: string;
  onNavigate: (id: string) => void;
};

export function MobileSheet({
  links,
  currentId,
  onNavigate,
}: MobileSheetProps) {
  const [isOpen, setIsOpen] = useState(false);

  function closeSheet() {
    setIsOpen(false);
  }

  return (
    <Sheet open={isOpen} onOpenChange={setIsOpen}>
      <SheetTrigger
        render={
          <Button
            variant='ghost'
            size='icon'
            className='md:hidden'
            aria-label='Open menu'
          />
        }
      >
        <MenuIcon />
      </SheetTrigger>
      <SheetContent side='right'>
        <SheetHeader>
          <SheetTitle className='flex items-center gap-2'>
            <FernpostMark />
            Fernpost
          </SheetTitle>
          <SheetDescription>
            Newsletters for people who write every week
          </SheetDescription>
        </SheetHeader>
        <nav aria-label='Main'>
          <ul className='flex flex-col gap-0.5'>
            {links.map((link) => {
              const isCurrent = currentId === link.id;

              function navigate() {
                onNavigate(link.id);
                closeSheet();
              }

              return (
                <li key={link.id}>
                  <a
                    href={link.href}
                    aria-current={currentAttributeOf(isCurrent)}
                    onClick={navigate}
                    className='text-foreground hover:bg-foreground/5 aria-[current=page]:bg-foreground/5 focus-visible:ring-ring/25 flex h-11 items-center justify-between rounded-md px-3 text-base font-medium transition-colors outline-none focus-visible:ring-[3px]'
                  >
                    {link.label}
                    {isCurrent && <SelectedMark />}
                  </a>
                </li>
              );
            })}
          </ul>
        </nav>
        <SheetFooter>
          <Button
            variant='outline'
            size='lg'
            nativeButton={false}
            render={<a href='#' />}
          >
            Sign in
          </Button>
          <Button size='lg' nativeButton={false} render={<a href='#' />}>
            Start writing
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
}

export type NavLink = {
  id: string;
  label: string;
  href: string;
};

export const NAV_LINKS: NavLink[] = [
  { id: 'features', label: 'Features', href: '#' },
  { id: 'pricing', label: 'Pricing', href: '#' },
  { id: 'changelog', label: 'Changelog', href: '#' },
  { id: 'docs', label: 'Docs', href: '#' },
];

export const DEFAULT_LINK_ID = 'features';
